class Solution {
public:
    int countHousePlacements(int n) {
        const long long MOD = 1000000007;
        long long r[2][2] = {{1, 0}, {0, 1}};
        long long mb[2][2] = {{1, 1}, {1, 0}};
        long long e = n + 1;
        while (e > 0) {
            if (e & 1) {
                long long na = (r[0][0] * mb[0][0] + r[0][1] * mb[1][0]) % MOD;
                long long nb = (r[0][0] * mb[0][1] + r[0][1] * mb[1][1]) % MOD;
                long long nc = (r[1][0] * mb[0][0] + r[1][1] * mb[1][0]) % MOD;
                long long nd = (r[1][0] * mb[0][1] + r[1][1] * mb[1][1]) % MOD;
                r[0][0] = na; r[0][1] = nb; r[1][0] = nc; r[1][1] = nd;
            }
            long long na = (mb[0][0] * mb[0][0] + mb[0][1] * mb[1][0]) % MOD;
            long long nb = (mb[0][0] * mb[0][1] + mb[0][1] * mb[1][1]) % MOD;
            long long nc = (mb[1][0] * mb[0][0] + mb[1][1] * mb[1][0]) % MOD;
            long long nd = (mb[1][0] * mb[0][1] + mb[1][1] * mb[1][1]) % MOD;
            mb[0][0] = na; mb[0][1] = nb; mb[1][0] = nc; mb[1][1] = nd;
            e >>= 1;
        }
        long long fn = r[0][0];
        return (int)((fn * fn) % MOD);
    }
};
